+++ b/authoring.domain.yaml
@@ -11,6 +11,7 @@
 roles:
 - owner
 - expert
+- deputy
 objects:
   Source:
     description: 'Where raw material lives: code, records, transcripts or the interview
@@ -519,10 +520,12 @@
       status: confirmed
   approve_commit:
     description: 'Approve a commit: merge it into main and tag it. Only a person approves.
+      The owner, or a deputy the owner has named while they are away, may approve.
       A commit whose change is wording only may be approved without a passing change
       check.'
     actor:
     - owner
+    - deputy
     target: Commit
     requires: human
     records_decision: true
